// 遗赠人的在世声明与撤回各占唯一永久事实；尚未处分任何财物或向受益人发送消息。
#include "family_bequest.hpp"
#include "family_continuation_people4.hpp"
#include <algorithm>
#include <charconv>
#include <map>
#include <set>
#include <tuple>
namespace hanmo::resident {
namespace {
// 身份号必须已分配；不同种类和领域不能借相同ID替代这份声明。
Status header(const CommonStore& c,const StableId& id,const StableId& kind){const StableId prefix="family_bequest:";if(id.rfind(prefix,0)!=0)return common_failure("InvalidBequestFact",id);Integer n=0;auto first=id.data()+prefix.size();auto parsed=std::from_chars(first,id.data()+id.size(),n);const auto* h=c.state().facts.find(id);return parsed.ec==std::errc{}&&parsed.ptr==id.data()+id.size()&&n>0&&n<c.state().next_instance_id&&id==prefix+std::to_string(n)&&h&&h->id==id&&h->kind==kind&&h->domain=="family_bequest"?common_success():common_failure("InvalidBequestFact",id);}
// 同tick仍使用实际Common插入顺序，不用数字ID排序猜先后。
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& ids=c.state().facts.order();auto x=std::find(ids.begin(),ids.end(),a),y=std::find(ids.begin(),ids.end(),b);return x!=ids.end()&&y!=ids.end()&&x<y;}
// 任何声明/撤回都不能由真实死亡以后的当事人补签。
Status alive_before(const CommonStore& c,const FamilyDeathState& deaths,const StableId& actor,Integer tick,const StableId& fact,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){if(people&&(!people->bound_to(c,deaths)||life4!=&people->life()))return common_failure("FamilyContinuationCandidateMismatch",{},ErrorKind::internal);if(life4){const auto* h=c.state().facts.find(fact);if(!h)return common_failure("BequestOriginalHeaderRequired",fact,ErrorKind::internal);return life4->require_no_death_before_original_fact(actor,tick,{h->domain,h->kind,fact});}for(const auto& row:deaths.deaths.rows())if(row.second.actor_id==actor&&(tick>row.second.death_tick||!before(c,fact,row.second.cause_fact_id)))return common_failure("BequestDecisionAfterDeath",fact);return common_success();}
// 报价代次绑定完整世界身份，避免重开存档后旧撤回按钮仍可提交。
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)==std::tie(b.world_id,b.execution_epoch,b.revision,b.tick);}
// 只确认历史原玩家，不借本人今天已经死亡/退隐反改旧授权。
Status donor_before(const FamilyBequestPlayerRead& read,const StableId& actor,Integer tick,const StableId& fact){if(!read)return common_failure("BequestHistoricalPlayerRequired",fact);auto player=read(tick,fact);if(!player.ok)return {false,{},player.error};return player.value==actor?common_success():common_failure("BequestHistoricalDonorMismatch",fact);}
}
const FamilyBequestDeclaration* active_family_bequest(const FamilyBequestState& state,const StableId& donor,StableId* id){for(const auto& row:state.declarations.rows())if(row.second.source.terms.donor_actor_id==donor){bool revoked=false;for(const auto& end:state.revocations.rows())if(end.second.declaration_id==row.first)revoked=true;if(!revoked){if(id)*id=row.first;return &row.second;}}return nullptr;}
Status validate_family_bequests(const CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,const FamilyBequestState& state,const FamilyBequestPlayerRead& read,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    if(policy.selected_version!=1&&policy.selected_version!=2)return common_failure("FamilyBequestVersionRequired",{},ErrorKind::unsupported_capability);if(policy.enabled&&policy.selected_version==2&&(!people||!life4||!people->bound_to(c,deaths)||&people->life()!=life4))return common_failure("BequestAgeSource2Required",{},ErrorKind::unsupported_capability);
    if(!policy.enabled){if(!state.declarations.empty()||!state.revocations.empty())return common_failure("FamilyBequestProfileRequired");for(const auto& row:c.state().facts.rows())if(row.second.domain=="family_bequest")return common_failure("FamilyBequestProfileRequired");return common_success();}if(life4&&!life4->bound_to(c,deaths))return common_failure("BequestLifeSourceCandidateMismatch",{},ErrorKind::internal);auto valid=life4?life4->validate():validate_family_deaths(c,deaths,origin,true);if(!valid.ok)return valid;std::set<StableId> ids,revoked,active;
    for(const auto& row:state.revocations.rows()){const auto& fact=row.second;const auto* declared=state.declarations.find(fact.declaration_id);if(fact.kind!="family_bequest_revocation"||!declared||!revoked.insert(fact.declaration_id).second||!ids.insert(row.first).second)return common_failure("InvalidBequestRevocation",row.first);valid=header(c,row.first,fact.kind);if(!valid.ok)return valid;const auto& source=declared->source;if(fact.donor_actor_id!=source.terms.donor_actor_id||fact.tick<source.tick||fact.tick>c.tick()||!before(c,fact.declaration_id,row.first))return common_failure("BequestRevocationSourceMismatch",row.first);valid=alive_before(c,deaths,fact.donor_actor_id,fact.tick,row.first,life4,people);if(!valid.ok)return valid;valid=donor_before(read,fact.donor_actor_id,fact.tick,row.first);if(!valid.ok)return valid;}
    for(const auto& row:state.declarations.rows()){const auto& fact=row.second;const auto& source=fact.source;const auto& terms=source.terms;if(fact.kind!="family_bequest_declaration"||!ids.insert(row.first).second)return common_failure("InvalidBequestDeclaration",row.first);valid=header(c,row.first,fact.kind);if(!valid.ok)return valid;valid=validate_family_bequest_source(c,family,source,policy.selected_version,people,row.first);if(!valid.ok)return valid;if(!before(c,terms.relation_fact_id,row.first))return common_failure("BequestBeforeRelationship",row.first);for(const auto* actor:{&terms.donor_actor_id,&terms.beneficiary_actor_id}){valid=alive_before(c,deaths,*actor,source.tick,row.first,life4,people);if(!valid.ok)return valid;}valid=donor_before(read,terms.donor_actor_id,source.tick,row.first);if(!valid.ok)return valid;if(!revoked.count(row.first)&&!active.insert(terms.donor_actor_id).second)return common_failure("MultipleActiveBequests",terms.donor_actor_id);}
    // 当前只剩一份不代表过去从未重叠；下一声明也须晚于上一份真实撤回。
    std::map<StableId,StableId> prior;for(const auto& id:c.state().facts.order())if(const auto* fact=state.declarations.find(id)){const auto& donor=fact->source.terms.donor_actor_id;auto previous=prior.find(donor);if(previous!=prior.end()){StableId ended;for(const auto& row:state.revocations.rows())if(row.second.declaration_id==previous->second)ended=row.first;if(ended.empty()||!before(c,ended,id))return common_failure("OverlappingBequestDeclarations",id);}prior[donor]=id;}
    for(const auto& row:c.state().facts.rows())if(row.second.domain=="family_bequest"&&!ids.count(row.first))return common_failure("MissingBequestFact",row.first);return common_success();
}
Outcome<StableId> record_family_bequest(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,FamilyBequestState& state,const FamilyBequestPlayerRead& read,const FamilyBequestDeclarationQuote& quote,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    auto valid=validate_family_bequests(c,family,deaths,origin,policy,state,read,life4,people);if(!valid.ok)return {false,{},valid.error};valid=revalidate_family_bequest_declaration(c,family,policy,quote,people);if(!valid.ok)return {false,{},valid.error};StableId prior;const auto* active=active_family_bequest(state,quote.source.terms.donor_actor_id,&prior);if(active)return family_bequest_source_equal(active->source,quote.source)?Outcome<StableId>{true,prior,{}}:Outcome<StableId>{false,{},common_failure("BequestAlreadyActive",prior).error};
    auto point=c.begin_savepoint();if(!point.ok)return {false,{},point.error};auto next=state;auto abort=[&](Status error)->Outcome<StableId>{auto rolled=c.rollback_savepoint(point.value);return {false,{},rolled.ok?error.error:rolled.error};};auto id=c.next_id("family_bequest");if(!id.ok)return abort({false,{},id.error});FamilyBequestDeclaration fact;fact.source=quote.source;if(!next.declarations.insert(id.value,fact))return abort(common_failure("DuplicateBequestFact"));valid=c.append_fact({id.value,fact.kind,"family_bequest"});if(!valid.ok)return abort(valid);valid=validate_family_bequests(c,family,deaths,origin,policy,next,read,life4,people);if(!valid.ok)return abort(valid);valid=c.commit_savepoint(point.value);if(!valid.ok)return {false,{},valid.error};state=std::move(next);return {true,id.value,{}};
}
Outcome<FamilyBequestRevocationQuote> preview_family_bequest_revocation(const CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,const FamilyBequestState& state,const FamilyBequestPlayerRead& read,const StableId& id,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    auto valid=validate_family_bequests(c,family,deaths,origin,policy,state,read,life4,people);if(!valid.ok)return {false,{},valid.error};const auto* fact=state.declarations.find(id);if(!fact)return {false,{},common_failure("UnknownBequestDeclaration",id).error};const auto& donor=fact->source.terms.donor_actor_id;const auto* person=c.actor(donor);if(donor!=c.state().metadata.player_actor_id||!person||!person->alive||!person->available)return {false,{},common_failure("BequestDonorAuthorityRequired",donor).error};for(const auto& row:state.revocations.rows())if(row.second.declaration_id==id)return {false,{},common_failure("BequestAlreadyRevoked",id).error};return {true,{c.state().identity,id,donor},{}};
}
Outcome<StableId> revoke_family_bequest(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,FamilyBequestState& state,const FamilyBequestPlayerRead& read,const FamilyBequestRevocationQuote& quote,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    if(!same_identity(c.state().identity,quote.identity))return {false,{},common_failure("StaleBequestRevocation").error};auto fresh=preview_family_bequest_revocation(c,family,deaths,origin,policy,state,read,quote.declaration_id,life4,people);if(!fresh.ok)return {false,{},fresh.error};if(fresh.value.donor_actor_id!=quote.donor_actor_id)return {false,{},common_failure("StaleBequestRevocation").error};
    auto point=c.begin_savepoint();if(!point.ok)return {false,{},point.error};auto next=state;auto abort=[&](Status error)->Outcome<StableId>{auto rolled=c.rollback_savepoint(point.value);return {false,{},rolled.ok?error.error:rolled.error};};auto id=c.next_id("family_bequest");if(!id.ok)return abort({false,{},id.error});FamilyBequestRevocation fact;fact.declaration_id=quote.declaration_id;fact.donor_actor_id=quote.donor_actor_id;fact.tick=c.tick();if(!next.revocations.insert(id.value,fact))return abort(common_failure("DuplicateBequestFact"));auto valid=c.append_fact({id.value,fact.kind,"family_bequest"});if(!valid.ok)return abort(valid);valid=validate_family_bequests(c,family,deaths,origin,policy,next,read,life4,people);if(!valid.ok)return abort(valid);valid=c.commit_savepoint(point.value);if(!valid.ok)return {false,{},valid.error};state=std::move(next);return {true,id.value,{}};
}
}
